     5→/* ---------- CSS Custom Properties ---------- */
     6→:root {
     7→  --color-primary:       #1d4ed8;
     8→  --color-primary-dark:  #1e40af;
     9→  --color-primary-light: #eff6ff;
    10→  --color-accent:        #7c3aed;
    11→  --color-accent-light:  #f5f3ff;
    12→
    13→  --color-bg:            #ffffff;
    14→  --color-bg-alt:        #f8fafc;
    15→  --color-bg-dark:       #0f172a;
    16→
    17→  --color-text:          #0f172a;
    18→  --color-text-muted:    #64748b;
    19→  --color-text-light:    #94a3b8;
    20→
    21→  --color-border:        #e2e8f0;
    22→  --color-card-bg:       #ffffff;
    23→
    24→  /* publication quality colours */
    25→  --color-q1:            #065f46;
    26→  --color-q1-bg:         #d1fae5;
    27→  --color-q2:            #1e40af;
    28→  --color-q2-bg:         #dbeafe;
    29→  --color-thesis:        #6b21a8;
    30→  --color-thesis-bg:     #f3e8ff;
    31→  --color-conf:          #92400e;
    32→  --color-conf-bg:       #fef3c7;
    33→  --color-preprint:      #be185d;
    34→  --color-preprint-bg:   #fce7f3;
    35→
    36→  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
    37→  --font-serif: 'Merriweather', Georgia, 'Times New Roman', serif;
    38→
    39→  --radius-sm:   6px;
    40→  --radius-md:   12px;
    41→  --radius-lg:   20px;
    42→  --radius-full: 9999px;
    43→
    44→  --shadow-sm:  0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
    45→  --shadow-md:  0 4px 16px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.05);
    46→  --shadow-lg:  0 10px 40px rgba(0,0,0,0.10), 0 4px 12px rgba(0,0,0,0.06);
    47→
    48→  --transition: 0.22s ease;
    49→  --nav-height: 68px;
    50→}
    51→
    52→/* ---------- Reset & Base ---------- */
    53→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    54→
    55→html { scroll-behavior: smooth; font-size: 16px; }
    56→
    57→body {
    58→  font-family: var(--font-sans);
    59→  color: var(--color-text);
    60→  background: var(--color-bg);
    61→  line-height: 1.7;
    62→  -webkit-font-smoothing: antialiased;
    63→  -moz-osx-font-smoothing: grayscale;
    64→}
    65→
    66→img { max-width: 100%; display: block; }
    67→a  { color: var(--color-primary); text-decoration: none; }
    68→a:hover { text-decoration: underline; }
    69→
    70→/* ---------- Utilities ---------- */
    71→.container {
    72→  max-width: 1080px;
    73→  margin: 0 auto;
    74→  padding: 0 24px;
    75→}
    76→
    77→.inline-link {
    78→  color: var(--color-primary);
    79→  font-weight: 500;
    80→  border-bottom: 1px solid transparent;
    81→  transition: border-color var(--transition);
    82→}
    83→.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }
    84→
    85→/* ---------- Buttons ---------- */
    86→.btn {
    87→  display: inline-flex;
    88→  align-items: center;
    89→  gap: 7px;
    90→  padding: 10px 22px;
    91→  border-radius: var(--radius-full);
    92→  font-size: 0.875rem;
    93→  font-weight: 600;
    94→  cursor: pointer;
    95→  transition: background var(--transition), color var(--transition),
    96→              border-color var(--transition), transform var(--transition),
    97→              box-shadow var(--transition);
    98→  border: 2px solid transparent;
    99→  text-decoration: none !important;
   100→  white-space: nowrap;

