   130→/* ---------- Navbar ---------- */
   131→.navbar {
   132→  position: fixed;
   133→  top: 0;
   134→  width: 100%;
   135→  height: var(--nav-height);
   136→  background: rgba(255,255,255,0.94);
   137→  backdrop-filter: blur(14px);
   138→  -webkit-backdrop-filter: blur(14px);
   139→  border-bottom: 1px solid var(--color-border);
   140→  z-index: 1000;
   141→  transition: box-shadow var(--transition);
   142→}
   143→.navbar.scrolled { box-shadow: var(--shadow-md); }
   144→
   145→.nav-container {
   146→  max-width: 1080px;
   147→  margin: 0 auto;
   148→  padding: 0 24px;
   149→  height: 100%;
   150→  display: flex;
   151→  align-items: center;
   152→  justify-content: space-between;
   153→}
   154→
   155→.nav-brand {
   156→  display: flex;
   157→  flex-direction: column;
   158→  text-decoration: none;
   159→}
   160→.nav-brand-name {
   161→  font-size: 1.0rem;
   162→  font-weight: 700;
   163→  color: var(--color-text);
   164→  letter-spacing: -0.02em;
   165→  line-height: 1.2;
   166→  transition: color var(--transition);
   167→}
   168→.nav-brand-sub {
   169→  font-size: 0.7rem;
   170→  font-weight: 400;
   171→  color: var(--color-text-muted);
   172→  letter-spacing: 0.02em;
   173→}
   174→.nav-brand:hover .nav-brand-name { color: var(--color-primary); }
   175→
   176→.nav-links {
   177→  list-style: none;
   178→  display: flex;
   179→  gap: 30px;
   180→}
   181→.nav-links a {
   182→  font-size: 0.875rem;
   183→  font-weight: 500;
   184→  color: var(--color-text-muted);
   185→  text-decoration: none;
   186→  transition: color var(--transition);
   187→  position: relative;
   188→}
   189→.nav-links a::after {
   190→  content: '';
   191→  position: absolute;
   192→  bottom: -4px;
   193→  left: 0;
   194→  width: 0;
   195→  height: 2px;
   196→  background: var(--color-primary);
   197→  border-radius: var(--radius-full);
   198→  transition: width var(--transition);
   199→}
   200→.nav-links a:hover,
   201→.nav-links a.active { color: var(--color-primary); }
   202→.nav-links a:hover::after,
   203→.nav-links a.active::after { width: 100%; }
   204→
   205→.nav-toggle {
   206→  display: none;
   207→  flex-direction: column;
   208→  gap: 5px;
   209→  background: none;
   210→  border: none;
   211→  cursor: pointer;
   212→  padding: 4px;
   213→}
   214→.nav-toggle span {
   215→  display: block;
   216→  width: 22px;
   217→  height: 2px;
   218→  background: var(--color-text);
   219→  border-radius: 2px;
   220→  transition: all var(--transition);
   221→}
   222→
   223→/* ---------- Hero ---------- */
   224→.hero {
   225→  min-height: 100vh;
   226→  display: flex;
   227→  flex-direction: column;
   228→  align-items: center;
   229→  justify-content: center;
   230→  padding: calc(var(--nav-height) + 60px) 24px 80px;
   231→  background: linear-gradient(135deg, #f0f9ff 0%, #eff6ff 40%, #f5f3ff 100%);
   232→  position: relative;
   233→  overflow: hidden;
   234→}
   235→
   236→.hero-bg-pattern {
   237→  position: absolute;
   238→  inset: 0;
   239→  background-image:
   240→    radial-gradient(circle at 20% 30%, rgba(29,78,216,0.06) 0%, transparent 50%),
   241→    radial-gradient(circle at 80% 70%, rgba(124,58,237,0.05) 0%, transparent 50%);
   242→  pointer-events: none;
   243→}
   244→
   245→.hero-content {
   246→  display: flex;
   247→  align-items: center;
   248→  gap: 64px;
   249→  max-width: 900px;

