   326→  transition: color var(--transition);
   327→}
   328→.scroll-down:hover { color: var(--color-primary); text-decoration: none; }
   329→@keyframes bounce {
   330→  0%, 100% { transform: translateX(-50%) translateY(0); }
   331→  50%       { transform: translateX(-50%) translateY(7px); }
   332→}
   333→
   334→/* ---------- Sections ---------- */
   335→.section { padding: 96px 0; }
   336→.section-alt { background: var(--color-bg-alt); }
   337→
