</head>
<body>

  <!-- ① Scroll progress bar -->
  <div id="scroll-progress" role="progressbar" aria-hidden="true"></div>

  <!-- ② Navbar -->
  <nav id="navbar" ...>
    [brand] [nav links: About, News, Research, Publications, CV, Contact] [theme-toggle button]
  </nav>

  <!-- ③ Hero -->
  <section id="hero" ...>
    [canvas#aurora-canvas OR .hero-bg-geo (CSS-only)]
