    [links: Google Scholar btn-primary | ResearchGate btn-outline | Download CV btn-outline | University Profile btn-ghost]
    [.scroll-indicator]
  </section>

  <!-- ④ About -->
  <section id="about" ...>
    [.about-metrics row: Citations | h-index | Publications | Years Active — animated counters]
    [.about-grid: bio text col | highlights col]
    [highlights: position card | dual-region card | publications since card]
  </section>

  <!-- ⑤ News (NEW) -->
  <section id="news" ...>
    [.news-grid: 4–6 .news-item cards in a 2-col grid]
    [each card: date badge | icon | headline | brief description]
  </section>

  <!-- ⑥ Research (ENHANCED) -->
  <section id="research" ...>
    [.research-projects: 2-3 featured project cards with methodology callouts]
    [.interests-grid: 4 interest cards (keep existing)]
  </section>

  <!-- ⑦ Timeline/CV (NEW) -->
  <section id="cv" ...>
    [.timeline: vertical line with alternating .timeline-item nodes]
    [items: MSc 2013–2015, Various early positions, PhD start 2019, PhD defense 2026, Postdoc]
  </section>

  <!-- ⑧ Publications (ENHANCED) -->
  <section id="publications" ...>
    [.pub-controls: search input | filter buttons | year-range display]
    [.pub-stats-bar: mini citation chart (canvas element)]
    [.pub-year-group × 7 years: existing card structure retained]
    [.scholar-cta]
  </section>

  <!-- ⑨ Contact -->
  <section id="contact" ...>
    [.contact-grid: 5 contact cards — existing structure, visual refresh only]
  </section>

  <!-- ⑩ Footer -->
  <footer ...>
    [copyright | social links | "built with" attribution]
  </footer>

  <script src="js/main.js"></script>
</body>
```

