**JS for search and filter:**

```js
// ---------- Publications filter + search ----------
const pubSearch = document.getElementById('pubSearch');
const filterBtns = document.querySelectorAll('.pub-filter-btn');
const pubCards = document.querySelectorAll('.publication-card');
const pubYearGroups = document.querySelectorAll('.pub-year-group');

let activeFilter = 'all';
let searchQuery = '';

function filterPublications() {
  let visibleCount = 0;

  pubCards.forEach(card => {
    const type = card.dataset.type;
    const text = card.textContent.toLowerCase();
    const matchesFilter = activeFilter === 'all' || type === activeFilter;
    const matchesSearch = searchQuery === '' || text.includes(searchQuery);
    const show = matchesFilter && matchesSearch;
    card.style.display = show ? '' : 'none';
    if (show) visibleCount++;
  });

  // Hide year group headers if all cards in them are hidden
  pubYearGroups.forEach(group => {
    const visible = [...group.querySelectorAll('.publication-card')]
      .some(c => c.style.display !== 'none');
    group.style.display = visible ? '' : 'none';
  });

  // Show empty state if needed
  const emptyEl = document.querySelector('.pub-empty');
  if (emptyEl) emptyEl.style.display = visibleCount === 0 ? 'block' : 'none';
}

filterBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    filterBtns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    activeFilter = btn.dataset.filter;
    filterPublications();
  });
});

if (pubSearch) {
  pubSearch.addEventListener('input', () => {
    searchQuery = pubSearch.value.toLowerCase().trim();
    filterPublications();
  });
}
```

**Citation sparkline visualization (Canvas):**

Add a small `<canvas>` element in the publications section header to visualize citation counts by year. This requires collecting the citation data from the HTML and drawing a simple bar chart:

```html
<!-- Inside .section-subtitle area for publications -->
<div class="citation-chart-wrap" aria-hidden="true">
  <canvas id="citationChart" width="320" height="60"></canvas>
  <p class="chart-caption">Citations by publication year</p>
</div>
```

JS (pure canvas, no libraries):

```js
function drawCitationChart() {
  const canvas = document.getElementById('citationChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  // Data: [year, citations] extracted from the cards
  const data = [
    [2017, 5], [2019, 7], [2020, 5], [2021, 2],
    [2022, 15], [2023, 6], [2024, 21], [2025, 2]
  ];

  const W = canvas.width;
  const H = canvas.height;
  const pad = 8;
  const maxVal = Math.max(...data.map(d => d[1]));
  const barW = (W - pad * (data.length + 1)) / data.length;
  const primaryColor = getComputedStyle(document.documentElement)
    .getPropertyValue('--color-accent').trim() || '#0e9e8e';

  ctx.clearRect(0, 0, W, H);

  data.forEach(([year, val], i) => {
    const barH = ((val / maxVal) * (H - 24));
    const x = pad + i * (barW + pad);
    const y = H - 16 - barH;

    ctx.fillStyle = primaryColor;
    ctx.globalAlpha = 0.8;
    // Rounded top bars
    const r = 3;
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + barW - r, y);
    ctx.quadraticCurveTo(x + barW, y, x + barW, y + r);
    ctx.lineTo(x + barW, y + barH);
    ctx.lineTo(x, y + barH);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    ctx.fill();

    // Year label
    ctx.globalAlpha = 0.6;
    ctx.fillStyle = getComputedStyle(document.documentElement)
      .getPropertyValue('--color-text-muted').trim() || '#4a5e78';
    ctx.font = '8px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText(year.toString().slice(2), x + barW / 2, H - 2);
  });
}

// Call after DOM ready and re-call on theme toggle for color updates
drawCitationChart();
```

Re-draw the chart on theme change by calling `drawCitationChart()` inside the theme toggle event listener.

